-- Additive only. No UPDATE, DELETE, dropped indexes or rewritten actor/user IDs.
ALTER TABLE "manifiestos" ADD COLUMN "contextoEmpresa" JSONB;
CREATE TABLE "empresas" ("id" TEXT PRIMARY KEY,"cuit" TEXT NOT NULL UNIQUE,"razonSocial" TEXT NOT NULL,"nombreFantasia" TEXT,"domicilioLegal" JSONB NOT NULL,"revision" INTEGER NOT NULL DEFAULT 0,"activa" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "empresas_actividades" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"rol" TEXT NOT NULL CHECK ("rol" IN ('GENERADOR','TRANSPORTISTA','OPERADOR')),"actorId" TEXT NOT NULL,"aprobadaPor" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"activa" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("empresaId","rol"),UNIQUE("rol","actorId"));
CREATE TABLE "empresas_establecimientos" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"codigo" TEXT NOT NULL,"nombre" TEXT NOT NULL,"domicilio" TEXT NOT NULL,"localidad" TEXT,"departamento" TEXT,"latitud" DOUBLE PRECISION,"longitud" DOUBLE PRECISION,"certificados" JSONB NOT NULL,"revision" INTEGER NOT NULL DEFAULT 0,"activo" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("empresaId","codigo"));
CREATE TABLE "empresas_responsables" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"usuarioId" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"validadoPor" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"validadoAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revocadoAt" TIMESTAMP(3),"motivo" TEXT NOT NULL,UNIQUE("empresaId","usuarioId"));
CREATE TABLE "empresas_autorizaciones" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"actividadId" TEXT NOT NULL REFERENCES "empresas_actividades"("id") ON DELETE RESTRICT,"usuarioId" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"todosEstablecimientos" BOOLEAN NOT NULL,"establecimientoIds" TEXT[] NOT NULL,"activa" BOOLEAN NOT NULL DEFAULT TRUE,"revision" INTEGER NOT NULL DEFAULT 0,"otorgadaPor" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("actividadId","usuarioId"));
CREATE INDEX "empresas_autorizaciones_usuarioId_activa_idx" ON "empresas_autorizaciones"("usuarioId","activa");
CREATE TABLE "empresas_invitaciones" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"actividadId" TEXT NOT NULL REFERENCES "empresas_actividades"("id") ON DELETE RESTRICT,"email" TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"todosEstablecimientos" BOOLEAN NOT NULL,"establecimientoIds" TEXT[] NOT NULL,"creadaPor" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"venceAt" TIMESTAMP(3) NOT NULL,"aceptadaPor" TEXT REFERENCES "usuarios"("id") ON DELETE RESTRICT,"aceptadaAt" TIMESTAMP(3),"revocadaAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "empresas_invitaciones_empresaId_email_idx" ON "empresas_invitaciones"("empresaId","email");
CREATE TABLE "empresas_eventos" ("id" TEXT PRIMARY KEY,"empresaId" TEXT NOT NULL REFERENCES "empresas"("id") ON DELETE RESTRICT,"usuarioId" TEXT NOT NULL REFERENCES "usuarios"("id") ON DELETE RESTRICT,"tipo" TEXT NOT NULL,"datos" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "empresas_eventos_empresaId_createdAt_idx" ON "empresas_eventos"("empresaId","createdAt");
CREATE TABLE "empresas_fuentes_padron" ("id" TEXT PRIMARY KEY,"sha256" TEXT NOT NULL,"archivo" TEXT NOT NULL,"hoja" TEXT NOT NULL,"fila" INTEGER NOT NULL,"contenidoHash" TEXT NOT NULL,"datos" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("sha256","hoja","fila"));
